<section class="directory-panel"><div class="panel-heading"><div><h2><?= $admin ? 'Tất cả người dùng' : 'Thành viên trong hệ thống' ?> <span class="count-badge"><?= $data['count'] ?></span></h2><p><?= $admin ? 'Quản lý thông tin và tài khoản tại một nơi.' : 'Danh sách được cập nhật trực tiếp từ cơ sở dữ liệu.' ?></p></div></div>
<div class="toolbar"><form method="get" action="<?= e(url('/index.php')) ?>" class="search-form" role="search"><input type="hidden" name="route" value="<?= $admin ? 'admin/users' : 'home' ?>"><label class="search-input"><?= icon('search') ?><span class="sr-only">Tìm theo email</span><input name="q" type="search" placeholder="Tìm kiếm theo email..." value="<?= e($search) ?>" maxlength="255"></label><button class="button button-outline button-small" type="submit">Tìm kiếm</button><?php if ($search !== ''): ?><a class="clear-search" href="<?= e(route_url($admin ? 'admin/users' : 'home')) ?>">Bỏ lọc</a><?php endif; ?></form><span class="result-count"><?= $search === '' ? 'Hiển thị' : 'Tìm thấy' ?> <strong><?= $data['count'] ?></strong> người dùng</span></div>
<?php if ($data['rows'] === []): ?><div class="empty-state"><?= icon('search') ?><h3>Chưa tìm thấy người dùng</h3><p><?= $search === '' ? 'Hãy thêm tài khoản đầu tiên từ khu vực quản trị.' : 'Thử một email khác hoặc bỏ bộ lọc tìm kiếm.' ?></p></div><?php else: ?>
<div class="table-scroll"><table><thead><tr><th scope="col" class="id-column">MÃ SỐ</th><th scope="col">NGƯỜI DÙNG</th><th scope="col">ẢNH ĐẠI DIỆN</th><th scope="col" class="table-end"><?= $admin ? 'THAO TÁC' : 'LOẠI TÀI KHOẢN' ?></th></tr></thead><tbody><?php foreach ($data['rows'] as $row): ?><tr><td class="id-cell">#<?= str_pad((string) $row['admin_id'], 3, '0', STR_PAD_LEFT) ?></td><td><div class="user-cell"><?php avatar($row); ?><div><strong><?= e($row['admin_email']) ?></strong></div></div></td><td><span class="image-status"><i class="<?= $row['images'] !== '' ? 'has-image' : '' ?>"></i><?= $row['images'] !== '' ? 'Đã có ảnh' : 'Ảnh mặc định' ?></span></td><td class="table-end"><?php if ($admin): ?><div class="row-actions"><a class="icon-button" href="<?= e(route_url('admin/user', ['id' => $row['admin_id']])) ?>" aria-label="Sửa <?= e($row['admin_email']) ?>" title="Sửa người dùng"><?= icon('edit') ?></a><button class="icon-button danger" type="button" data-delete-id="<?= $row['admin_id'] ?>" data-delete-email="<?= e($row['admin_email']) ?>" aria-label="Xóa <?= e($row['admin_email']) ?>" title="Xóa người dùng" <?= $row['admin_id'] === $currentUser['admin_id'] ? 'disabled' : '' ?>><?= icon('trash') ?></button></div><?php else: ?><span class="role-badge"><?= $row['is_admin'] ? 'Quản trị viên' : 'Người dùng' ?></span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php endif; ?>
<div class="pagination"><span><?= $data['count'] ? 'Hiển thị ' . (($data['page'] - 1) * 8 + 1) . '–' . min($data['page'] * 8, $data['count']) . ' trên ' . $data['count'] : '0' ?> người dùng</span><nav aria-label="Phân trang"><?php $listRoute = $admin ? 'admin/users' : 'home'; ?><?php if ($data['page'] > 1): ?><a class="page-button" href="<?= e(route_url($listRoute, ['q' => $search, 'page' => $data['page'] - 1])) ?>">← Trước</a><?php endif; ?><span class="page-number" aria-current="page"><?= $data['page'] ?></span><span class="page-total">/ <?= $data['pages'] ?></span><?php if ($data['page'] < $data['pages']): ?><a class="page-button" href="<?= e(route_url($listRoute, ['q' => $search, 'page' => $data['page'] + 1])) ?>">Sau →</a><?php endif; ?></nav></div></section>
<?php if ($admin): ?><dialog id="delete-dialog"><form action="<?= e(route_url('admin/delete')) ?>" method="post"><?php csrf_field(); ?><input type="hidden" name="id" id="delete-id"><span class="dialog-icon"><?= icon('trash') ?></span><h2>Xóa người dùng?</h2><p>Tài khoản <strong id="delete-email"></strong> và ảnh tải lên sẽ bị xóa. Thao tác này không thể hoàn tác.</p><div class="form-actions"><button type="button" class="button button-outline" id="cancel-delete">Hủy</button><button class="button button-danger" type="submit">Xóa người dùng</button></div></form></dialog><?php endif; ?>
